def _clean(s):
    # \/ escapes the char right after it (shields a literal ':'
    # through the blanket strip below).
    out = []
    i = 0
    while i < len(s):
        if s[i] == '\\' and i + 2 < len(s) and s[i + 1] == '/':
            c = s[i + 2]
            out.append('\x00' if c == ':' else c)
            i += 3
        else:
            out.append(s[i])
            i += 1
    joined = ''.join(out).replace(':', '')
    return joined.replace('\x00', ':')

def _is_numeric(s):
    t = s[1:] if s.startswith('-') else s
    return t.isnumeric()

def _math(left, right, op):
    l = int(left) if _is_numeric(left) else 0
    r = int(right) if _is_numeric(right) else 0
    if op == '+': return l + r
    if op == '-': return l - r
    if op in ('*', 'x'): return l * r
    if op == '/': return l // r if r != 0 else 0
    if op == '%': return l % r if r != 0 else 0
    return 0

def _test(left, right, op):
    if op == '==': return left == right
    if op == '!=': return left != right
    try:
        l, r = float(left), float(right)
    except ValueError:
        return False
    if op == '>': return l > r
    if op == '<': return l < r
    if op == '>=': return l >= r
    if op == '<=': return l <= r
    return False

